// Cycle-level checks use expected values generated by the Python integer oracle.
`timescale 1ns/1ps
module tb_fpga_v8_affine_add;
    parameter integer LANES = 16;
    reg clk;
    reg rst_n;
    reg [LANES*8-1:0] s_data_a;
    reg [LANES*8-1:0] s_data_b;
    reg s_valid;
    wire s_ready;
    reg s_last;
    reg [31:0] scale_a;
    reg [31:0] scale_b;
    reg [7:0] zp_a;
    reg [7:0] zp_b;
    reg [7:0] zp_out;
    wire [LANES*8-1:0] m_data;
    wire m_valid;
    reg m_ready;
    wire m_last;
    reg expected_ready;
    reg expected_valid;
    reg [LANES*8-1:0] expected_data;
    reg expected_last;
    reg [8191:0] input_path;
    integer fd;
    integer fields;
    integer cycle;
    integer errors;
    integer accepted;
    integer consumed;
    integer reset_pending;
    integer stalled;
    integer last_consumed;
    integer simultaneous;

    fpga_v8_affine_add #(.LANES(LANES)) dut (
        .clk(clk), .rst_n(rst_n), .s_data_a(s_data_a), .s_data_b(s_data_b),
        .s_valid(s_valid), .s_ready(s_ready), .s_last(s_last),
        .scale_a(scale_a), .scale_b(scale_b),
        .zp_a(zp_a), .zp_b(zp_b), .zp_out(zp_out),
        .m_data(m_data), .m_valid(m_valid), .m_ready(m_ready), .m_last(m_last)
    );

    initial begin
        clk = 1'b0;
        forever #5 clk = !clk;
    end

    initial begin
        rst_n = 1'b0;
        s_valid = 1'b0;
        s_last = 1'b0;
        s_data_a = 0;
        s_data_b = 0;
        scale_a = 0;
        scale_b = 0;
        zp_a = 0;
        zp_b = 0;
        zp_out = 0;
        m_ready = 1'b0;
        cycle = 0;
        errors = 0;
        accepted = 0;
        consumed = 0;
        reset_pending = 0;
        stalled = 0;
        last_consumed = 0;
        simultaneous = 0;
        if (!$value$plusargs("INPUT=%s", input_path)) begin
            $display("FAIL: missing +INPUT");
            $finish;
        end
        fd = $fopen(input_path, "r");
        if (fd == 0) begin
            $display("FAIL: cannot open input file");
            $finish;
        end
        while (!$feof(fd)) begin
            @(negedge clk);
            // Count a pending word before an asynchronous reset can flush it.
            fields = $fscanf(fd,
                "%b %b %b %b %h %h %h %h %h %h %h %b %b %h %b\n",
                rst_n, s_valid, s_last, m_ready, s_data_a, s_data_b,
                scale_a, scale_b, zp_a, zp_b, zp_out,
                expected_ready, expected_valid, expected_data, expected_last);
            if (fields == 15) begin
                if (!rst_n && m_valid) reset_pending = reset_pending + 1;
                #1;
                if (s_ready !== expected_ready) begin
                    $display("FAIL cycle=%0d ready got=%b expected=%b",
                             cycle, s_ready, expected_ready);
                    errors = errors + 1;
                end
                if (!rst_n && ((m_valid !== 0) || (m_data !== 0) || (m_last !== 0))) begin
                    $display("FAIL cycle=%0d asynchronous reset did not clear outputs", cycle);
                    errors = errors + 1;
                end
                if (rst_n && m_valid && !m_ready) stalled = stalled + 1;
                if (rst_n && s_valid && s_ready) accepted = accepted + 1;
                if (rst_n && m_valid && m_ready) begin
                    consumed = consumed + 1;
                    if (m_last) last_consumed = last_consumed + 1;
                    if (s_valid && s_ready) simultaneous = simultaneous + 1;
                end
                @(posedge clk);
                #1;
                if (m_valid !== expected_valid) begin
                    $display("FAIL cycle=%0d valid got=%b expected=%b",
                             cycle, m_valid, expected_valid);
                    errors = errors + 1;
                end
                if (expected_valid &&
                    ((m_data !== expected_data) || (m_last !== expected_last))) begin
                    $display("FAIL cycle=%0d data got=%h expected=%h last=%b/%b",
                             cycle, m_data, expected_data, m_last, expected_last);
                    errors = errors + 1;
                end
                if (!rst_n && ((m_data !== 0) || (m_last !== 0))) begin
                    $display("FAIL cycle=%0d reset did not clear outputs", cycle);
                    errors = errors + 1;
                end
                cycle = cycle + 1;
                if (errors > 10) begin
                    $display("FAIL: too many errors");
                    $finish;
                end
            end else if (fields != -1) begin
                $display("FAIL: malformed vector, fields=%0d", fields);
                $finish;
            end
        end
        $fclose(fd);
        if (m_valid) begin
            $display("FAIL: undrained output at end");
            errors = errors + 1;
        end
        if ((reset_pending < 2) || (stalled < 10) ||
            (last_consumed < 2) || (simultaneous < 10)) begin
            $display("FAIL: inadequate handshake coverage");
            errors = errors + 1;
        end
        if (errors == 0)
            $display("PASS lanes=%0d cycles=%0d accepted=%0d consumed=%0d reset_pending=%0d stalled=%0d last=%0d simultaneous=%0d",
                     LANES, cycle, accepted, consumed, reset_pending,
                     stalled, last_consumed, simultaneous);
        else
            $display("FAIL errors=%0d", errors);
        $finish;
    end

    initial begin
        #1000000;
        $display("FAIL: watchdog timeout");
        $finish;
    end
endmodule
